    /**
 * Module: alu_16bit
 * Description: A 16-bit Arithmetic Logic Unit (ALU) implementing various 
 *              arithmetic, logical, and shift operations.
 *              Outputs are registered and synchronous.
 */
module alu_16bit (
    input wire clk,
    input wire rst,
    input wire [15:0] a,
    input wire [15:0] b,
    input wire [3:0] opcode,
    output reg [15:0] result,
    output reg zero,
    output reg overflow,
    output reg negative
);

    // Internal wires for combinational logic
    reg [15:0] temp_result;
    reg temp_overflow;
    
    // Shift amount is the low 4 bits of B for a 16-bit width (log2(16)=4)
    // However, the prompt requirements specifically mentioned B[4:0] 
    // and "low log2(WIDTH) bits". For 16-bit, log2(16) is 4.
    // We use b[3:0] to avoid out-of-bounds shift for 16-bit result.
    wire [3:0] shamt = b[3:0];

    always @(*) begin
        // Default values to avoid latches
        temp_result = 16'b0;
        temp_overflow = 1'b0;

        case (opcode)
            4'b0000: begin // ADD: Signed Addition
                temp_result = a + b;
                // Signed overflow: (pos+pos=neg) or (neg+neg=pos)
                temp_overflow = (a[15] == b[15]) && (temp_result[15] != a[15]);
            end

            4'b0001: begin // SUB: Signed Subtraction
                temp_result = a - b;
                // Signed overflow: (pos-neg=neg) or (neg-pos=pos)
                temp_overflow = (a[15] != b[15]) && (temp_result[15] != a[15]);
            end

            4'b0010: begin // AND: Bitwise AND
                temp_result = a & b;
            end

            4'b0011: begin // OR: Bitwise OR
                temp_result = a | b;
            end

            4'b0100: begin // XOR: Bitwise XOR
                temp_result = a ^ b;
            end

            4'b0101: begin // SLL: Logical Left Shift
                temp_result = a << shamt;
            end

            4'b0110: begin // SRL: Logical Right Shift
                temp_result = a >> shamt;
            end

            4'b0111: begin // SRA: Arithmetic Right Shift
                // Verilog $signed() ensures arithmetic shift for reg/wire
                temp_result = $signed(a) >>> shamt;
            end

            4'b1000: begin // SLT: Signed Set Less Than
                if ($signed(a) < $signed(b))
                    temp_result = 16'd1;
                else
                    temp_result = 16'd0;
            end

            4'b1001: begin // SLTU: Unsigned Set Less Than
                if (a < b)
                    temp_result = 16'd1;
                else
                    temp_result = 16'd0;
            end

            default: begin // Default case
                temp_result = 16'b0;
            end
        endcase
    end

    // Sequential logic for output registers
    always @(posedge clk) begin
        if (rst) begin
            result   <= 16'b0;
            zero     <= 1'b0;
            overflow <= 1'b0;
            negative <= 1'b0;
        end else begin
            result   <= temp_result;
            zero     <= (temp_result == 16'b0);
            overflow <= temp_overflow;
            negative <= temp_result[15];
        end
    end

endmodule